select id, tobe_shipped, expressnotreceived, outstandingpayment, have_Tailfunds, CONVERT(batchM USING utf8mb4) AS 'batchM', CONVERT(batchY USING utf8mb4) AS 'batchY', CONVERT(commodityM USING utf8mb4) AS 'commodityM', CONVERT(commodityY USING utf8mb4) AS 'commodityY', CONVERT(contractM USING utf8mb4) AS 'contractM', CONVERT(contractY USING utf8mb4) AS 'contractY', CONVERT(signfor_expressdelivery USING utf8mb4) AS 'signfor_expressdelivery', CONVERT(express_evaluation USING utf8mb4) AS 'express_evaluation', CONVERT(shipment_status USING utf8mb4) AS 'shipment_status', update_date, DATE_FORMAT( record_date , '%Y-%m-%d' ) as 'record_date', dept_id from yz_agent_asset_details
record_date = #{record_date} and dept_id = #{dept_id}
order by update_date desc LIMIT 1
